import json
with open('/root/.nanobot/config.json') as f:
    cfg = json.load(f)

# Redact all secrets
for provider, data in cfg.get('providers', {}).items():
    if data.get('apiKey'):
        data['apiKey'] = ''
    if data.get('apiBase'):
        data['apiBase'] = ''

for channel, data in cfg.get('channels', {}).items():
    for secret_field in ['token', 'appId', 'secret', 'clientId', 'clientSecret', 
                          'botToken', 'appToken', 'accessToken', 'apiKey']:
        if data.get(secret_field):
            data[secret_field] = ''
    if isinstance(data, dict):
        for k,v in data.items():
            if 'token' in k.lower() or 'key' in k.lower() or 'secret' in k.lower():
                if isinstance(v, str) and v:
                    data[k] = ''

# MCP server keys
for name, srv in cfg.get('tools', {}).get('mcpServers', {}).items():
    if srv.get('headers'):
        for k,v in srv['headers'].items():
            if 'key' in k.lower() or 'token' in k.lower() or 'auth' in k.lower():
                srv['headers'][k] = ''
    if srv.get('env'):
        for k in srv['env']:
            if 'key' in k.lower() or 'token' in k.lower() or 'secret' in k.lower() or 'password' in k.lower():
                srv['env'][k] = ''

# Search API key
if cfg.get('tools', {}).get('web', {}).get('search', {}).get('apiKey'):
    cfg['tools']['web']['search']['apiKey'] = ''

with open('config.example.json', 'w') as f:
    json.dump(cfg, f, indent=2, ensure_ascii=False)
print('Done')
print('Size:', __import__('os').path.getsize('config.example.json'), 'bytes')
"
